import {thermalNodes, thermalStates, deriveBound} from './thermal-limits.js';
import {helpButton} from './input-help-ui.js';
import {icon} from './icons.js';
const f=(n,d=1)=>Number.isFinite(n)?n.toLocaleString('en-US',{maximumFractionDigits:d}):'—';
const esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
export const boundFields=thermalNodes.flatMap(n=>thermalStates.flatMap(state=>['min','max'].map(side=>({id:n.id,state,side,key:n.keys[state][side]}))));
export function sanitizeTargets(value){return Object.fromEntries(boundFields.filter(b=>value?.[b.key]==='derive').map(b=>[b.key,'derive']))}
export function requirementResults(view,summary,d){
 return boundFields.filter(b=>view.thermalTargets?.[b.key]==='derive').map(b=>({...deriveBound(summary,b.id,b.state,b.side,view.thermalPadding||0),specifiedRatingK:d[b.key],selectedScope:view.thermalScope||'window'}));
}
export function thermalInspector(view,h,s,summary,clock){
 const node=thermalNodes.find(x=>x.id===view.thermalNode)||thermalNodes[0],now=s.thermalQualification.find(r=>r.id===node.id),scope=view.thermalScope==='mission'?'mission':'window',ready=!!summary,margin=view.thermalPadding||0;
 const hint=(key,label,option='')=>view.phase==='A'?helpButton(key,label,option):'';
 const selectField=(id,title,guide,value,choices)=>`<div class="fieldbox"><div class="field-caption"><label for="${id}">${esc(title)}</label>${hint(guide,title,value)}</div><select id="${id}">${choices.map(([k,label])=>`<option value="${esc(k)}" ${k===value?'selected':''}>${esc(label)}</option>`).join('')}</select></div>`;
 const rows=thermalStates.map(state=>{
 const obs=summary?.rows.find(r=>r.id===node.id&&r.state===state),lowDuration=(obs?.lowSeconds||0)/60,highDuration=(obs?.highSeconds||0)/60;
 return `<section class="limit-card"><h3>${state==='operating'?'Operating':'Survival'} range <small>${state==='operating'?'IN SERVICE':'STANDBY'}</small></h3>${['min','max'].map(side=>{
 const key=node.keys[state][side],controlId='role-'+key,derived=view.thermalTargets?.[key]==='derive',out=deriveBound(summary,node.id,state,side,margin),input=`<input aria-label="Specified ${state} ${side} in kelvin" class="numinput" type="number" min="3" max="1500" step=".1" value="${h.input[key]}" data-rating="${key}">`;
 return `<div class="limit-row"><div class="fieldbox"><div class="field-caption"><label for="${controlId}">${side==='min'?'Lower':'Upper'} bound</label>${hint('thermalRole',node.label+' '+state+' '+side+' role',derived?'derive':'input')}</div><select id="${controlId}" data-bound-role="${key}" aria-label="${esc(node.label)} ${state} ${side} mode"><option value="input" ${!derived?'selected':''}>Input rating</option><option value="derive" ${derived?'selected':''}>Solve requirement</option></select></div><div>${hint(key,node.label+' '+state+' '+side+' rating')} ${derived?`<strong class="limit-value">${out.valueK!==null?f(out.valueK,2)+' K':out.status==='infeasible'?'Infeasible bound':ready?'No state coverage':'Sweep needed'}</strong><small>Specified rating ${f(h.input[key])} K</small>${out.status==='derived'?'<button class="textbutton" data-adopt-rating="'+key+'" data-tip="Set the computed requirement as this design’s specified rating and switch the bound to input mode.">Use as input</button>':''}${out.status==='infeasible'?'<div class="limit-note">'+esc(out.reason)+' Required '+f(out.requiredK,2)+' K.</div>':''}`:`${input} <em>K</em>`}</div></div>`}).join('')}<p>${obs?.durationS>0?`Observed ${f(obs.minK,2)}–${f(obs.maxK,2)} K during ${f(obs.durationS/3600,2)} h. ${f(lowDuration,2)} min below and ${f(highDuration,2)} min above the specified limits.`:ready?'No observations in this state during the selected interval.':'Run the chronological sweep for mission-wide observations.'}</p>${obs?.durationS>0?'<div class="limit-time"><button class="chip" data-thermal-instant="'+obs.minTime+'" data-tip="Show the coldest observed instant in this state in the spacecraft thermal view.">Inspect minimum</button><button class="chip" data-thermal-instant="'+obs.maxTime+'" data-tip="Show the hottest observed instant in this state in the spacecraft thermal view.">Inspect maximum</button></div>':''}</section>`}).join('');
 return `<p>Compare the component’s temperature with its specified rating for the current activity. Solve a required bound from the coldest or hottest observation plus the chosen margin. Specified hardware ratings remain the basis for pass/fail.</p><div class="limit-filters">${selectField('thermal-node','Component','thermalNode',node.id,thermalNodes.map(n=>[n.id,n.label]))}${selectField('thermal-scope','Coverage','thermalScope',scope,[['window','Selected 24-hour window'],['mission','Entire mission · chronological']])}<div class="fieldbox"><div class="field-caption"><label for="thermal-pad">Design margin (K)</label>${hint('thermalPadding','requirement margin')}</div><input id="thermal-pad" class="numinput" min="0" max="100" step=".1" type="number" value="${margin}"></div></div><div class="thermal-now ${['cold','hot'].includes(now.status)?'outside':''}"><strong>${f(now.temperatureK,2)} K</strong><div>${esc(now.activity)} · ${esc(now.state)} limits ${f(now.minK)}–${f(now.maxK)} K<br><small>${now.status==='unassessed'?'Outside modeled coverage':now.status==='pass'?'In range by '+f(now.marginK,2)+' K':'Outside range by '+f(-now.marginK,2)+' K'} at ${esc(clock)}</small></div></div><div class="limit-grid">${rows}</div>${!ready?'<button class="btn export" data-action="thermal-audit">Run mission temperature sweep</button>':''}<p class="model-footnote">${ready?esc(summary.provenance)+' · '+f(summary.coveredSeconds/3600,2)+' modeled hours. ':''}Initial ratings are engineering assumptions. A solved bound describes the temperature tolerance the observed mission requires.</p>`;
}
export function temperatureFacts(q){return q?`<div class="thermal-now ${['cold','hot'].includes(q.status)?'outside':''}"><strong>${f(q.temperatureK,1)} K</strong><div>${esc(q.label)} · ${esc(q.activity)}<br><small>${esc(q.state)} range ${f(q.minK)}–${f(q.maxK)} K · ${q.status==='pass'?'in range':q.status==='unassessed'?'unassessed':f(Math.abs(q.marginK),1)+' K '+(q.status==='cold'?'below minimum':'above maximum')}</small></div></div>`:''}

